class Solution:
    def getPermutationIndex(self, perm: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(perm)
        fact = [1] * n
        for i in range(1, n): fact[i] = fact[i-1] * i % MOD
        tree = [0] * (n + 1)
        def upd(i, d):
            while i <= n: tree[i] += d; i += i & -i
        def qry(i):
            s = 0
            while i: s += tree[i]; i -= i & -i
            return s
        for i in range(1, n + 1): upd(i, 1)
        ans = 0
        for i, x in enumerate(perm):
            ans = (ans + qry(x - 1) * fact[n - 1 - i]) % MOD
            upd(x, -1)
        return ans

