class Solution {
public:
    int getPermutationIndex(vector<int>& perm) {
        const long long MOD = 1e9 + 7;
        int n = perm.size();
        vector<long long> fact(n, 1);
        for (int i = 1; i < n; i++) fact[i] = fact[i-1] * i % MOD;
        vector<int> tree(n + 1, 0);
        auto upd = [&](int i, int d) { for (; i <= n; i += i & -i) tree[i] += d; };
        auto qry = [&](int i) { long long s = 0; for (; i > 0; i -= i & -i) s += tree[i]; return s; };
        for (int i = 1; i <= n; i++) upd(i, 1);
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            ans = (ans + qry(perm[i] - 1) % MOD * fact[n - 1 - i]) % MOD;
            upd(perm[i], -1);
        }
        return ans;
    }
};

