class Solution {
    public int getPermutationIndex(int[] perm) {
        final long MOD = 1_000_000_007L;
        int n = perm.length;
        long[] fact = new long[n];
        fact[0] = 1;
        for (int i = 1; i < n; i++) fact[i] = fact[i-1] * i % MOD;
        long[] tree = new long[n + 1];
        for (int i = 1; i <= n; i++)
            for (int j = i; j <= n; j += j & -j) tree[j] += 1;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long s = 0;
            for (int j = perm[i] - 1; j > 0; j -= j & -j) s += tree[j];
            ans = (ans + s % MOD * fact[n - 1 - i]) % MOD;
            for (int j = perm[i]; j <= n; j += j & -j) tree[j] -= 1;
        }
        return (int) ans;
    }
}

