class Solution {
public:
    int getPermutationIndex(vector<int>& perm) {
        const long long MOD = 1e9 + 7;
        int n = perm.size();
        vector<long long> fact(n, 1);
        for (int i = 1; i < n; i++) fact[i] = fact[i-1] * i % MOD;
        vector<long long> cnt(n, 0);
        vector<int> a = perm;
        function<void(int,int)> go = [&](int lo, int hi) {
            if (hi - lo < 2) return;
            int mid = (lo + hi) / 2;
            go(lo, mid); go(mid, hi);
            vector<int> tmp; int i = lo, j = mid;
            while (i < mid || j < hi) {
                if (j == hi || (i < mid && a[i] <= a[j])) {
                    cnt[a[i]-1] += j - mid; tmp.push_back(a[i++]);
                } else tmp.push_back(a[j++]);
            }
            for (int k = lo; k < hi; k++) a[k] = tmp[k - lo];
        };
        go(0, n);
        long long ans = 0;
        for (int i = 0; i < n; i++)
            ans = (ans + cnt[i] % MOD * fact[n-1-i]) % MOD;
        return ans;
    }
};

