class Solution {
    private long[] cnt;
    private int[] a;
    private void go(int lo, int hi) {
        if (hi - lo < 2) return;
        int mid = (lo + hi) / 2;
        go(lo, mid); go(mid, hi);
        int[] tmp = new int[hi - lo];
        int i = lo, j = mid, k = 0;
        while (i < mid || j < hi) {
            if (j == hi || (i < mid && a[i] <= a[j])) {
                cnt[a[i]-1] += j - mid; tmp[k++] = a[i++];
            } else tmp[k++] = a[j++];
        }
        System.arraycopy(tmp, 0, a, lo, hi - lo);
    }
    public int getPermutationIndex(int[] perm) {
        final long MOD = 1_000_000_007L;
        int n = perm.length;
        long[] fact = new long[n];
        fact[0] = 1;
        for (int i = 1; i < n; i++) fact[i] = fact[i-1] * i % MOD;
        cnt = new long[n]; a = perm.clone();
        go(0, n);
        long ans = 0;
        for (int i = 0; i < n; i++) ans = (ans + cnt[i] % MOD * fact[n-1-i]) % MOD;
        return (int) ans;
    }
}

